mapper.select:
select
c.*
from
eg_charge_off_summary_report c
where
c.period_code = #{param.periodCode}
and c.del_flag =  '0'

    and c.contract_code like concat('%', #{param.contractCode}::text, '%')


    and c.org_id = #{param.orgId}


    and c.verification_status = #{param.verificationStatus}


    and c.verification_date = #{param.verificationDate}

order by
c.provision_reversal_year asc
